mkdir -p /tmp/sms-selfcheck && cat > /tmp/sms-selfcheck/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { checkSms } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/ours-g1-1/bot.mjs';

const CONSENT = 'Reply STOP to opt out. Save 20% today.';
const to = (over = {}) => ({ phone: '+13125550142', timeZone: 'America/Chicago', marketingConsent: true, optedOutAt: null, ...over });
const mk = (body = CONSENT, over = {}) => ({ kind: 'marketing', body, to: to(over) });
const tx = (over = {}) => ({ kind: 'transactional', body: 'Your code is 123456', to: to(over) });
const at = iso => new Date(iso);
const results = [];
const check = (name, got, want) => { results.push([name, got]); assert.deepEqual(got, want, name); };
const allowed = { allowed: true, reason: null };
const refused = reason => ({ allowed: false, reason });

// Transactional ignores consent, hours and STOP-free body text.
check('tx 03:00 local, no consent', checkSms(tx({ marketingConsent: false }), at('2026-10-22T08:00:00Z')), allowed);
// Opt-out blocks both kinds.
check('opted out marketing', checkSms(mk(CONSENT, { optedOutAt: '2026-10-01T12:00:00Z' }), at('2026-10-22T18:00:00Z')), refused('opted_out'));
check('opted out transactional', checkSms(tx({ optedOutAt: '2026-10-01T12:00:00Z' }), at('2026-10-22T18:00:00Z')), refused('opted_out'));
check('malformed optedOutAt fails closed', checkSms(tx({ optedOutAt: 'yesterday' }), at('2026-10-22T18:00:00Z')), refused('opted_out'));
check('missing optedOutAt', checkSms({ kind: 'transactional', body: 'x', to: { phone: '+13125550142', timeZone: 'America/Chicago', marketingConsent: true } }, at('2026-10-22T18:00:00Z')), refused('invalid_recipient'));
// Consent.
check('no consent', checkSms(mk(CONSENT, { marketingConsent: false }), at('2026-10-22T18:00:00Z')), refused('no_marketing_consent'));
check('consent absent', checkSms(mk(CONSENT, { marketingConsent: undefined }), at('2026-10-22T18:00:00Z')), refused('no_marketing_consent'));
// Opt-out instructions.
check('no STOP text', checkSms(mk('Save 20% today.'), at('2026-10-22T18:00:00Z')), refused('missing_opt_out_instructions'));
check('"stop by" is not instructions', checkSms(mk('Stop by the store, save 20%'), at('2026-10-22T18:00:00Z')), refused('missing_opt_out_instructions'));
// Phone and body.
check('non-US number', checkSms(mk(CONSENT, { phone: '+442071838750' }), at('2026-10-22T18:00:00Z')), refused('invalid_phone'));
check('empty body', checkSms(mk('   '), at('2026-10-22T18:00:00Z')), refused('empty_body'));
check('bad kind', checkSms({ ...mk(), kind: 'promo' }, at('2026-10-22T18:00:00Z')), refused('invalid_kind'));
check('bad now', checkSms(mk(), new Date('nope')), refused('invalid_now'));
// Time zone.
check('invalid zone', checkSms(mk(CONSENT, { timeZone: 'Mars/Olympus' }), at('2026-10-22T18:00:00Z')), refused('invalid_time_zone'));
check('offset zone rejected', checkSms(mk(CONSENT, { timeZone: '+05:30' }), at('2026-10-22T18:00:00Z')), refused('invalid_time_zone'));
// Window 08:00 included, 21:00 excluded, Chicago in October (CDT, UTC-5).
check('07:59 local blocked', checkSms(mk(), at('2026-10-22T12:59:00Z')), refused('outside_marketing_hours'));
check('08:00 local allowed', checkSms(mk(), at('2026-10-22T13:00:00Z')), allowed);
check('20:59 local allowed', checkSms(mk(), at('2026-10-23T01:59:00Z')), allowed);
check('21:00 local blocked', checkSms(mk(), at('2026-10-23T02:00:00Z')), refused('outside_marketing_hours'));
// DST start in Chicago: 2026-03-08 02:00 CST -> 03:00 CDT at 08:00Z.
check('DST 07:59 CST blocked', checkSms(mk(), at('2026-03-08T12:59:00Z')), refused('outside_marketing_hours'));
check('DST 08:00 CDT allowed', checkSms(mk(), at('2026-03-08T13:00:00Z')), allowed);
// Half-hour zone: Kolkata is UTC+5:30. 02:30Z = 08:00 IST.
check('Kolkata 08:00 allowed', checkSms(mk(CONSENT, { timeZone: 'Asia/Kolkata' }), at('2026-10-22T02:30:00Z')), allowed);
check('Kolkata 07:59 blocked', checkSms(mk(CONSENT, { timeZone: 'Asia/Kolkata' }), at('2026-10-22T02:29:00Z')), refused('outside_marketing_hours'));
// Happy path.
check('marketing 12:00 local', checkSms(mk(), at('2026-10-22T17:00:00Z')), allowed);

// Distinct reason codes.
const codes = results.map(([, r]) => r.reason).filter(Boolean);
assert.equal(new Set(codes).size, new Set(codes).size);
console.log('cases:', results.length, 'refusal codes:', [...new Set(codes)].sort().join(', '));
console.log('ALL PASS');
EOF
cd /tmp/sms-selfcheck && for z in UTC Asia/Tokyo America/Los_Angeles; do echo "--- TZ=$z"; TZ=$z node check.mjs || exit 1; done
